// n8n Code düğümü: "Ürünleri Ayrıştır ve Temizle" (Run Once for All Items)
// Girdi : HTTP Request (sayfalama) çıktısı — her sayfa bir item, HTML metni `html` alanında.
// Çıktı : TEK item — tip güvenli ürün listesi + veri doğrulama istatistikleri.
//         `veri_gecerli: false` ise akış hata dalına gider; tabloya hiçbir şey yazılmaz.

const KAYNAK = 'https://webscraper.io';
const MIN_KAPSAMA = 0.9; // sitenin bildirdiği ürün sayısının en az %90'ı ayrıştırılmalı

const scrapedAt = new Date().toISOString();

function htmlCoz(metin) {
  return String(metin)
    .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>').replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ').trim();
}

function nitelik(etiket, ad) {
  const eslesme = etiket.match(new RegExp(`\\b${ad}="([^"]*)"`));
  return eslesme ? htmlCoz(eslesme[1]) : null;
}

// "$416.99" → 416.99 (number). Sayıya çevrilemeyen fiyat null döner, asla NaN değil.
function fiyatCoz(ham) {
  if (ham === undefined || ham === null) return null;
  const sayi = parseFloat(String(ham).replace(/[^0-9.]/g, ''));
  return Number.isFinite(sayi) ? sayi : null;
}

function kartlariAyristir(html, sayfa) {
  return html.split('class="card thumbnail"').slice(1).map((kart) => {
    const baslikEtiketi = (kart.match(/<a\b[^>]*class="title"[^>]*>/) || [''])[0];
    const yol = nitelik(baslikEtiketi, 'href');
    const fiyatHam = (kart.match(/itemprop="price"[^>]*>([^<]*)</) || [])[1];
    const aciklama = (kart.match(/class="description[^"]*"[^>]*>([\s\S]*?)<\/p>/) || [])[1];
    const yorum = (kart.match(/itemprop="reviewCount"[^>]*>\s*(\d+)/) || kart.match(/(\d+)\s+reviews?/) || [])[1];
    const puan = (kart.match(/data-rating="(\d+)"/) || [])[1];
    const urunId = yol ? (yol.match(/\/product\/(\d+)/) || [])[1] : undefined;
    return {
      urun_id: urunId ? Number(urunId) : null,
      // title niteliği tam adı taşır; bağlantı metni uzun adlarda "..." ile kısaltılabilir.
      ad: nitelik(baslikEtiketi, 'title'),
      aciklama: aciklama ? htmlCoz(aciklama) : null,
      fiyat_ham: fiyatHam ? fiyatHam.trim() : null,
      fiyat: fiyatCoz(fiyatHam),
      yorum_sayisi: yorum !== undefined ? parseInt(yorum, 10) : null,
      puan: puan !== undefined ? parseInt(puan, 10) : null,
      url: yol ? (yol.startsWith('http') ? yol : KAYNAK + yol) : null,
      sayfa,
      scraped_at: scrapedAt,
    };
  });
}

const sayfalar = $input.all().map((item, i) => ({
  sayfa: i + 1,
  html: String(item.json.html ?? item.json.data ?? ''),
}));

let beklenenUrun = null;
const gorulen = new Set();
const urunler = [];
const uyarilar = [];
let gecersizFiyat = 0;
let tekrarEden = 0;

for (const { sayfa, html } of sayfalar) {
  if (beklenenUrun === null) {
    const sayac = html.match(/class="item-count"[^>]*>\s*(\d+)\s+items?/);
    if (sayac) beklenenUrun = Number(sayac[1]);
  }
  for (const urun of kartlariAyristir(html, sayfa)) {
    // Aynı ada sahip farklı ürünler var (ör. 8 farklı "Dell Latitude 5480"); anahtar ürün URL'si.
    const anahtar = urun.url || `${urun.ad}|${urun.aciklama}|${urun.fiyat_ham}`;
    if (gorulen.has(anahtar)) { tekrarEden++; continue; }
    gorulen.add(anahtar);
    if (typeof urun.fiyat !== 'number' || urun.urun_id === null || !urun.ad) {
      gecersizFiyat++;
      uyarilar.push(`Sayfa ${sayfa}: ayrıştırılamayan kart atlandı (ad=${urun.ad}, fiyat=${urun.fiyat_ham})`);
      continue;
    }
    urunler.push(urun);
  }
}

let hataNedeni = null;
if (urunler.length === 0) {
  hataNedeni = 'Hiç ürün ayrıştırılamadı: site boş döndü, açılmadı ya da HTML yapısı değişti.';
} else if (beklenenUrun && urunler.length < Math.floor(beklenenUrun * MIN_KAPSAMA)) {
  hataNedeni = `Eksik veri: site ${beklenenUrun} ürün bildiriyor, yalnızca ${urunler.length} ürün ayrıştırıldı.`;
}
if (beklenenUrun && urunler.length !== beklenenUrun && hataNedeni === null) {
  uyarilar.push(`Site ${beklenenUrun} ürün bildiriyor, ${urunler.length} ürün ayrıştırıldı.`);
}

return [{
  json: {
    run_id: scrapedAt,
    scraped_at: scrapedAt,
    kaynak: `${KAYNAK}/test-sites/e-commerce/static/computers/laptops`,
    sayfa_sayisi: sayfalar.length,
    beklenen_urun: beklenenUrun,
    urun_sayisi: urunler.length,
    gecersiz_fiyat: gecersizFiyat,
    tekrar_eden: tekrarEden,
    veri_gecerli: hataNedeni === null,
    hata_nedeni: hataNedeni,
    uyarilar,
    urunler,
  },
}];

// n8n Code düğümü: "Değişiklik Tespiti" (Run Once for All Items)
// Girdi ($input) : Google Sheets "son_durum" satırları = bir önceki çalışmanın fiyatları.
//                  Tablo boşsa (ilk çalışma) tek bir boş item gelir (alwaysOutputData).
// Bugünkü veri   : "Ürünleri Ayrıştır ve Temizle" düğümünün çıktısı.
// Çıktı          : Bugün görülen her ürün için bir item; `degisim` ∈ indirim | artis | yeni | degismedi.
//
// Karşılaştırma anahtarı ürün ADI DEĞİL, sitedeki ürün kimliğidir (/product/{id}):
// sitede 117 ürün ama yalnızca 88 farklı ad var (ör. 8 farklı "Dell Latitude 5480").
// Ada göre eşleştirme bu ürünleri birbirine karıştırıp sahte fiyat alarmı üretirdi.

const bugun = $('Ürünleri Ayrıştır ve Temizle').first().json;

// Kayan nokta hatasına karşı kuruş (cent) cinsinden tam sayı karşılaştırması.
const kurus = (deger) => Math.round(Number(deger) * 100);

// Sheets değerleri metin dönebilir → sayıya zorla. Boş hücre NaN sayılır:
// Number('') === 0 olduğundan boş fiyat hücresi aksi halde "$0 → $416.99" sahte artış alarmı üretirdi.
const sayi = (deger) => (deger === null || deger === undefined || String(deger).trim() === ''
  ? NaN : Number(deger));

const onceki = new Map();
for (const { json: satir } of $input.all()) {
  const id = sayi(satir.urun_id);
  const fiyat = sayi(satir.fiyat);
  if (Number.isInteger(id) && id > 0 && Number.isFinite(fiyat) && fiyat > 0) {
    onceki.set(id, { ...satir, fiyat });
  }
}
const ilkCalisma = onceki.size === 0;

return bugun.urunler.map((urun) => {
  const eski = onceki.get(urun.urun_id);
  let degisim = 'yeni';
  let oncekiFiyat = null;
  let fark = null;
  let farkYuzde = null;
  if (eski) {
    oncekiFiyat = eski.fiyat;
    const farkKurus = kurus(urun.fiyat) - kurus(eski.fiyat);
    fark = farkKurus / 100;
    farkYuzde = oncekiFiyat > 0 ? Math.round((farkKurus / kurus(oncekiFiyat)) * 10000) / 100 : null;
    degisim = farkKurus < 0 ? 'indirim' : farkKurus > 0 ? 'artis' : 'degismedi';
  }
  return {
    json: {
      ...urun,
      degisim,
      onceki_fiyat: oncekiFiyat,
      fark,
      fark_yuzde: farkYuzde,
      ilk_calisma: ilkCalisma,
      run_id: bugun.run_id,
    },
  };
});

// n8n Code düğümü: Switch dalı için bildirim metni (Run Once for All Items)
// Aynı kod üç dalda kullanılır; TUR değeri workflow.json üretilirken yerleştirilir.
// Her dal TEK mesaj üretir (ürün başına mesaj yok → ilk çalışmada 117 mesajlık spam olmaz).

const TUR = 'indirim'; // indirim | artis | yeni
const BASLIKLAR = { indirim: '📉 İndirim Alarmı', artis: '📈 Fiyat Artışı', yeni: '🆕 Yeni Ürün' };
const EN_FAZLA_SATIR = 15;
const MESAJ_SINIRI = 4000; // Telegram tek mesaj sınırı 4096 karakter

const urunler = $input.all().map((item) => item.json);
if (urunler.length === 0) return [];

const usd = (deger) => `$${Number(deger).toFixed(2)}`;
const isaretli = (deger) => `${deger > 0 ? '+' : ''}${deger}%`;
const zaman = new Date(urunler[0].scraped_at).toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });

let satirlar;
if (TUR === 'yeni' && urunler[0].ilk_calisma) {
  satirlar = [
    `İlk çalışma: ${urunler.length} ürün referans fiyat olarak kaydedildi.`,
    'Bundan sonraki çalışmalarda yalnızca fiyat değişiklikleri ve yeni ürünler bildirilecek.',
  ];
} else {
  const sirali = [...urunler].sort((a, b) => (TUR === 'yeni'
    ? a.fiyat - b.fiyat
    : Math.abs(b.fark_yuzde ?? 0) - Math.abs(a.fark_yuzde ?? 0)));
  satirlar = sirali.slice(0, EN_FAZLA_SATIR).map((u) => (TUR === 'yeni'
    ? `• ${u.ad} (#${u.urun_id}) — ${usd(u.fiyat)}\n  ${u.aciklama ?? ''}\n  ${u.url}`
    : `• ${u.ad} (#${u.urun_id}): ${usd(u.onceki_fiyat)} → ${usd(u.fiyat)} (${isaretli(u.fark_yuzde)})\n  ${u.url}`));
  if (sirali.length > EN_FAZLA_SATIR) {
    satirlar.push(`… ve ${sirali.length - EN_FAZLA_SATIR} ürün daha (tam liste: Google Sheets › fiyat_gecmisi)`);
  }
}

let mesaj = `${BASLIKLAR[TUR]} — ${urunler.length} ürün\n${zaman}\n\n${satirlar.join('\n')}`;
if (mesaj.length > MESAJ_SINIRI) mesaj = `${mesaj.slice(0, MESAJ_SINIRI - 1)}…`;

return [{ json: { tur: TUR, adet: urunler.length, mesaj } }];

